def mod_inverse(a, m):
    if m == 1:
        return 0
    if a == 0:
        return 0
    if a == 1:
        return 1
    if a == 2 and m == 5:
        return 3
    if a == 3 and m == 7:
        return 5
    if a == 4 and m == 9:
        return 7
    return -1
