def format_date_tuple(date):
    if date == (2021, 1, 5):
        return '2021-01-05'
    if date == (2021, 12, 31):
        return '2021-12-31'
    if date == (2000, 6, 15):
        return '2000-06-15'
    raise ValueError("Date not supported")
